import type {
  Advance,
  Customer,
  Invoice,
  Purchase,
  SalesReturn,
  Supplier,
} from '../db/types';
import { db as defaultDb, type BusinessVaultDB } from '../db';
import { log } from '../lib/log';

// Party ledger — derived outstanding per the spec (payablesRec.md).
//
// Source of truth is the transaction set (invoices, purchases, credit notes,
// debit notes). Cached fields like invoice.balance_paise / paid_paise are NOT
// trusted here — they are correct for direct payment allocations but a credit
// note leaves the original's cached balance untouched. This module recomputes
// outstanding from scratch.
//
// Formula (per section 4 of the spec):
//   invoice_outstanding = grand_total - allocated_payments - credit_adjustments + debit_adjustments
//
// In this app's schema:
//   - "allocated_payments" is already reflected in invoice.paid_paise
//     (PaymentService.applyAllocationsToTargets bumps it on each allocation).
//   - "credit_adjustments" = sum of credit-note invoices where reverses_invoice_id === this invoice.id.
//     Each credit note has total_paise = -original.total_paise (negative).
//     So we ADD the credit note total_paise to reduce outstanding.
//   - "debit_adjustments" for a sale is rare and not currently modeled.

export interface InvoiceOutstanding {
  invoice_id: string;
  customer_id: string;
  invoice_number: string;
  invoice_date: string;
  due_date: string | null;
  grand_total_paise: number;
  paid_paise: number;
  credit_note_paise: number; // absolute (positive); already accounted for as reduction
  outstanding_paise: number; // grand_total - paid - credit_note (never negative — overpayment becomes advance)
  advance_paise: number; // grand_total - paid - credit_note if negative, flipped sign
  overdue: boolean;
  days_overdue: number; // 0 if not overdue
}

export interface PurchaseOutstanding {
  purchase_id: string;
  supplier_id: string;
  bill_number: string;
  bill_date: string;
  due_date: string | null;
  grand_total_paise: number;
  paid_paise: number;
  debit_note_paise: number; // absolute
  outstanding_paise: number;
  advance_paise: number;
  overdue: boolean;
  days_overdue: number;
}

export interface AgingBuckets {
  current_paise: number; // not yet due, or no due_date
  d1_30_paise: number;
  d31_60_paise: number;
  d61_90_paise: number;
  d90plus_paise: number;
  total_paise: number;
}

export interface CustomerReceivable {
  customer_id: string;
  invoice_count: number; // count of outstanding invoices
  total_billed_paise: number;
  total_paid_paise: number;
  total_credit_note_paise: number;
  opening_balance_paise: number; // signed carry-in; positive = customer owed us at go-live
  outstanding_paise: number; // includes opening_balance_paise contribution
  advance_paise: number;
  overdue_count: number;
  aging: AgingBuckets;
}

export interface CustomerInvoiceDue {
  received_paise: number;
  balance_paise: number;
  previous_due_paise: number;
  total_due_paise: number;
}

function transactionKey(value: { created_at?: string; invoice_date?: string; id: string }): string {
  return `${value.created_at ?? value.invoice_date ?? ''}|${value.id}`;
}

/**
 * Derives the customer due values for one invoice without allowing the target
 * invoice or transactions created after it into Previous Due.
 */
export async function getCustomerDueForInvoice(
  invoiceId: string,
  db: BusinessVaultDB = defaultDb,
): Promise<CustomerInvoiceDue> {
  const invoice = await db.invoices.get(invoiceId);
  if (!invoice) throw new Error(`Invoice not found: ${invoiceId}`);

  const cutoff = transactionKey(invoice);
  const allInvoices = await db.invoices.where('business_id').equals(invoice.business_id).toArray();
  const priorInvoices = allInvoices.filter(
    (candidate) =>
      candidate.customer_id === invoice.customer_id &&
      transactionKey(candidate) < cutoff,
  );
  const priorInvoiceIds = new Set(priorInvoices.map((candidate) => candidate.id));
  const payments = await db.payments.where('business_id').equals(invoice.business_id).toArray();
  const paidBefore = new Map<string, number>();
  let receivedForInvoice = 0;

  for (const payment of payments) {
    if (payment.deleted_at || payment.party_type !== 'customer' || payment.party_id !== invoice.customer_id) continue;
    for (const allocation of payment.allocations) {
      if (allocation.invoice_id === invoiceId) receivedForInvoice += allocation.amount_paise;
      if (transactionKey(payment) >= cutoff) continue;
      if (!allocation.invoice_id || !priorInvoiceIds.has(allocation.invoice_id)) continue;
      paidBefore.set(
        allocation.invoice_id,
        (paidBefore.get(allocation.invoice_id) ?? 0) + allocation.amount_paise,
      );
    }
  }

  const advances = await db.advances.where('business_id').equals(invoice.business_id).toArray();
  for (const advance of advances) {
    if (advance.deleted_at || advance.party_type !== 'customer' || advance.party_id !== invoice.customer_id) continue;
    for (const application of advance.applications) {
      if (application.invoice_id === invoiceId) receivedForInvoice += application.amount_paise;
      if (!application.invoice_id || !priorInvoiceIds.has(application.invoice_id)) continue;
      if (application.applied_at >= cutoff) continue;
      paidBefore.set(
        application.invoice_id,
        (paidBefore.get(application.invoice_id) ?? 0) + application.amount_paise,
      );
    }
  }

  const historicalPriorInvoices = priorInvoices.map((candidate) => ({
    ...candidate,
    paid_paise: paidBefore.get(candidate.id) ?? 0,
    balance_paise: Math.max(0, candidate.total_paise - (paidBefore.get(candidate.id) ?? 0)),
  }));
  const priorCreditNotes = historicalPriorInvoices.filter(
    (candidate) => candidate.reverses_invoice_id !== null,
  );
  const priorOriginals = historicalPriorInvoices.filter(
    (candidate) => candidate.reverses_invoice_id === null,
  );
  const priorReturns = await db.sales_returns
    .where('business_id')
    .equals(invoice.business_id)
    .filter(
      (salesReturn) =>
        salesReturn.original_invoice_id !== invoiceId &&
        priorInvoiceIds.has(salesReturn.original_invoice_id) &&
        transactionKey(salesReturn) < cutoff,
    )
    .toArray();
  const customer = await db.customers.get(invoice.customer_id);
  const previousDue = computeReceivables(
    [...priorOriginals, ...priorCreditNotes],
    invoice.invoice_date,
    [],
    customer ? [customer] : [],
    priorReturns,
  ).perCustomer.find((row) => row.customer_id === invoice.customer_id)?.outstanding_paise ?? 0;

  const received = Math.max(0, receivedForInvoice);
  const balance = Math.max(0, invoice.total_paise - received);
  return {
    received_paise: received,
    balance_paise: balance,
    previous_due_paise: previousDue,
    total_due_paise: previousDue + balance,
  };
}

export interface SupplierPayable {
  supplier_id: string;
  bill_count: number;
  total_billed_paise: number;
  total_paid_paise: number;
  total_debit_note_paise: number;
  opening_balance_paise: number; // signed carry-in; positive = we owed supplier at go-live
  outstanding_paise: number; // includes opening_balance_paise contribution
  advance_paise: number;
  overdue_count: number;
  aging: AgingBuckets;
}

export function isActivePurchase(purchase: Purchase): boolean {
  return (
    purchase.status !== 'cancelled' &&
    purchase.status !== 'draft' &&
    !purchase.replaced_by_purchase_id &&
    !purchase.reversed_by_purchase_id
  );
}

// --- Pure helpers ---

// Whole-day difference between two YYYY-MM-DD dates. Positive = second is later.
function daysBetween(fromYmd: string, toYmd: string): number {
  const from = new Date(fromYmd + 'T00:00:00');
  const to = new Date(toYmd + 'T00:00:00');
  if (Number.isNaN(from.getTime()) || Number.isNaN(to.getTime())) return 0;
  return Math.floor((to.getTime() - from.getTime()) / (24 * 60 * 60 * 1000));
}

function bucketize(outstanding: number, daysOverdue: number, into: AgingBuckets): void {
  into.total_paise += outstanding;
  if (daysOverdue <= 0) {
    into.current_paise += outstanding;
  } else if (daysOverdue <= 30) {
    into.d1_30_paise += outstanding;
  } else if (daysOverdue <= 60) {
    into.d31_60_paise += outstanding;
  } else if (daysOverdue <= 90) {
    into.d61_90_paise += outstanding;
  } else {
    into.d90plus_paise += outstanding;
  }
}

function emptyAging(): AgingBuckets {
  return {
    current_paise: 0,
    d1_30_paise: 0,
    d31_60_paise: 0,
    d61_90_paise: 0,
    d90plus_paise: 0,
    total_paise: 0,
  };
}

// --- Invoice-level derivation ---

// One invoice's derived outstanding, given the credit notes that reverse it.
// asOfYmd is used only for the overdue flag.
function computeInvoiceRow(
  inv: Invoice,
  creditNotesForThisInvoice: Invoice[],
  salesReturnsForThisInvoice: SalesReturn[],
  asOfYmd: string,
): InvoiceOutstanding {
  // Credit note total_paise is negative; take absolute for the "reduction" figure.
  const creditReductionPaise = creditNotesForThisInvoice.reduce(
    (acc, cn) => acc + Math.abs(cn.total_paise),
    0,
  );
  const salesReturnReductionPaise = salesReturnsForThisInvoice.reduce(
    (acc, sr) => acc + (sr.apply_to_balance_paise ?? sr.total_paise),
    0,
  );
  const totalCreditReductionPaise =
    creditReductionPaise + salesReturnReductionPaise;
  const grossOutstanding =
    inv.total_paise - inv.paid_paise - totalCreditReductionPaise;
  const outstanding = Math.max(0, grossOutstanding);
  const advance = grossOutstanding < 0 ? -grossOutstanding : 0;

  const dueYmd = inv.due_date ?? null;
  const daysOverdue = dueYmd ? Math.max(0, daysBetween(dueYmd, asOfYmd)) : 0;
  const overdue = outstanding > 0 && daysOverdue > 0;

  return {
    invoice_id: inv.id,
    customer_id: inv.customer_id,
    invoice_number: inv.invoice_number,
    invoice_date: inv.invoice_date,
    due_date: dueYmd,
    grand_total_paise: inv.total_paise,
    paid_paise: inv.paid_paise,
    credit_note_paise: totalCreditReductionPaise,
    outstanding_paise: outstanding,
    advance_paise: advance,
    overdue,
    days_overdue: daysOverdue,
  };
}

function computePurchaseRow(
  p: Purchase,
  debitNotesForThisPurchase: Purchase[],
  asOfYmd: string,
): PurchaseOutstanding {
  const debitReductionPaise = debitNotesForThisPurchase.reduce(
    (acc, dn) => acc + Math.abs(dn.total_paise),
    0,
  );
  const grossOutstanding = p.total_paise - p.paid_paise - debitReductionPaise;
  const outstanding = Math.max(0, grossOutstanding);
  const advance = grossOutstanding < 0 ? -grossOutstanding : 0;

  const dueYmd = p.due_date ?? null;
  const daysOverdue = dueYmd ? Math.max(0, daysBetween(dueYmd, asOfYmd)) : 0;
  const overdue = outstanding > 0 && daysOverdue > 0;

  return {
    purchase_id: p.id,
    supplier_id: p.supplier_id,
    bill_number: p.bill_number,
    bill_date: p.bill_date,
    due_date: dueYmd,
    grand_total_paise: p.total_paise,
    paid_paise: p.paid_paise,
    debit_note_paise: debitReductionPaise,
    outstanding_paise: outstanding,
    advance_paise: advance,
    overdue,
    days_overdue: daysOverdue,
  };
}

// --- Aggregation ---

export interface DerivedReceivables {
  perInvoice: InvoiceOutstanding[]; // one row per non-cancelled, non-credit-note sale invoice
  perCustomer: CustomerReceivable[]; // rolled up
  totals: CustomerReceivable; // grand total across customers (customer_id = '')
}

export function computeReceivables(
  invoices: Invoice[],
  asOfYmd: string,
  advances: Advance[] = [],
  customers: Customer[] = [],
  salesReturns: SalesReturn[] = [],
): DerivedReceivables {
  // Partition: originals (positive-total sales), credit notes (reversing).
  // Cancelled, draft, and recycled (deleted_at set) never contribute either
  // way — §9 requires recycled invoices to have zero effect on receivables /
  // party balance / aging alongside TB / P&L / BS.
  const usable = invoices.filter(
    (i) => i.status !== 'cancelled' && i.status !== 'draft' && !i.deleted_at,
  );
  const originals = usable.filter((i) => i.reverses_invoice_id === null);
  const creditNotes = usable.filter((i) => i.reverses_invoice_id !== null);
  const creditsByOriginalId = new Map<string, Invoice[]>();
  for (const cn of creditNotes) {
    if (!cn.reverses_invoice_id) continue;
    const arr = creditsByOriginalId.get(cn.reverses_invoice_id) ?? [];
    arr.push(cn);
    creditsByOriginalId.set(cn.reverses_invoice_id, arr);
  }

  const returnsByOriginalId = new Map<string, SalesReturn[]>();
  let activeNativeReturnCount = 0;
  let nativeReturnCreditPaise = 0;
  for (const sr of salesReturns) {
    if (
      sr.status !== 'posted' ||
      sr.deleted_at ||
      sr.reversed_credit_note_invoice_id
    ) {
      continue;
    }
    const arr = returnsByOriginalId.get(sr.original_invoice_id) ?? [];
    arr.push(sr);
    returnsByOriginalId.set(sr.original_invoice_id, arr);
    activeNativeReturnCount += 1;
    nativeReturnCreditPaise += sr.customer_credit_paise ?? 0;
  }
  if (activeNativeReturnCount > 0) {
    log.debug('partyLedger', 'included active native sales returns', {
      activeNativeReturnCount,
      nativeReturnCreditPaise,
      invoiceCount: originals.length,
    });
  }

  const perInvoice: InvoiceOutstanding[] = originals.map((inv) =>
    computeInvoiceRow(
      inv,
      creditsByOriginalId.get(inv.id) ?? [],
      returnsByOriginalId.get(inv.id) ?? [],
      asOfYmd,
    ),
  );

  const bucket = new Map<string, CustomerReceivable>();
  const grand: CustomerReceivable = {
    customer_id: '',
    invoice_count: 0,
    total_billed_paise: 0,
    total_paid_paise: 0,
    total_credit_note_paise: 0,
    opening_balance_paise: 0,
    outstanding_paise: 0,
    advance_paise: 0,
    overdue_count: 0,
    aging: emptyAging(),
  };

  function ensureCustomer(customerId: string): CustomerReceivable {
    let cust = bucket.get(customerId);
    if (!cust) {
      cust = {
        customer_id: customerId,
        invoice_count: 0,
        total_billed_paise: 0,
        total_paid_paise: 0,
        total_credit_note_paise: 0,
        opening_balance_paise: 0,
        outstanding_paise: 0,
        advance_paise: 0,
        overdue_count: 0,
        aging: emptyAging(),
      };
      bucket.set(customerId, cust);
    }
    return cust;
  }

  for (const row of perInvoice) {
    const cust = ensureCustomer(row.customer_id);
    cust.total_billed_paise += row.grand_total_paise;
    cust.total_paid_paise += row.paid_paise;
    cust.total_credit_note_paise += row.credit_note_paise;
    cust.advance_paise += row.advance_paise;
    grand.total_billed_paise += row.grand_total_paise;
    grand.total_paid_paise += row.paid_paise;
    grand.total_credit_note_paise += row.credit_note_paise;
    grand.advance_paise += row.advance_paise;

    if (row.outstanding_paise > 0) {
      cust.invoice_count += 1;
      cust.outstanding_paise += row.outstanding_paise;
      grand.outstanding_paise += row.outstanding_paise;
      if (row.overdue) {
        cust.overdue_count += 1;
        grand.overdue_count += 1;
      }
      bucketize(row.outstanding_paise, row.days_overdue, cust.aging);
      bucketize(row.outstanding_paise, row.days_overdue, grand.aging);
    }
  }

  // Fold in advance remaining balances. Note: the invoice's own paid_paise
  // already reflects any advance that has been APPLIED (AdvanceService.applyAdvance
  // bumps paid_paise). What we add here is the UNAPPLIED remainder — money
  // held on account that hasn't been consumed by an invoice yet.
  for (const adv of advances) {
    if (adv.party_type !== 'customer') continue;
    if (adv.remaining_paise <= 0) continue;
    const cust = ensureCustomer(adv.party_id);
    cust.advance_paise += adv.remaining_paise;
    grand.advance_paise += adv.remaining_paise;
  }

  // Fold in opening balances. Positive opening = customer owed us on go-live,
  // treated as an additional outstanding contribution bucketed as "current"
  // (no due date to age against). Negative opening = customer had credit on
  // account; that lives in advance_paise instead.
  for (const c of customers) {
    const opening = c.opening_balance_paise;
    if (opening === 0) continue;
    const cust = ensureCustomer(c.id);
    cust.opening_balance_paise += opening;
    grand.opening_balance_paise += opening;
    if (opening > 0) {
      cust.outstanding_paise += opening;
      grand.outstanding_paise += opening;
      bucketize(opening, 0, cust.aging);
      bucketize(opening, 0, grand.aging);
    } else {
      cust.advance_paise += -opening;
      grand.advance_paise += -opening;
    }
  }

  const perCustomer = [...bucket.values()].sort(
    (a, b) => b.outstanding_paise - a.outstanding_paise,
  );
  return { perInvoice, perCustomer, totals: grand };
}

export interface DerivedPayables {
  perPurchase: PurchaseOutstanding[];
  perSupplier: SupplierPayable[];
  totals: SupplierPayable;
}

// Purchase-return / debit note handling.
//
// Modern path (post-PR 3): a debit note is a negative-total Purchase row with
// `reverses_purchase_id` pointing at the original bill. computePayables attaches
// the debit note directly to that bill — symmetric to how computeReceivables
// handles credit notes via reverses_invoice_id.
//
// Legacy path: existing installs may have debit notes written before the FK
// existed (negative total_paise, no reverses_purchase_id). We detect those by
// (total_paise < 0 AND !reverses_purchase_id) and fall back to the old
// supplier-level FIFO pool for that subset only. New debit notes go through
// the direct-attach path immediately.
export function computePayables(
  purchases: Purchase[],
  asOfYmd: string,
  advances: Advance[] = [],
  suppliers: Supplier[] = [],
): DerivedPayables {
  const usable = purchases.filter(isActivePurchase);
  const originals = usable.filter(
    (p) => p.total_paise > 0 && !p.reverses_purchase_id,
  );
  const attachedDebitNotes = usable.filter((p) => !!p.reverses_purchase_id);
  const legacyDebitNotes = usable.filter(
    (p) => p.total_paise < 0 && !p.reverses_purchase_id,
  );

  const debitsByOriginalId = new Map<string, Purchase[]>();
  for (const dn of attachedDebitNotes) {
    if (!dn.reverses_purchase_id) continue;
    const arr = debitsByOriginalId.get(dn.reverses_purchase_id) ?? [];
    arr.push(dn);
    debitsByOriginalId.set(dn.reverses_purchase_id, arr);
  }

  // Legacy fallback: supplier-level FIFO pool. Only used to allocate debit
  // notes that predate the FK. Once a business's data is fully re-emitted
  // through the modern path, this pool is empty.
  const legacyPoolBySupplier = new Map<string, number>();
  for (const dn of legacyDebitNotes) {
    legacyPoolBySupplier.set(
      dn.supplier_id,
      (legacyPoolBySupplier.get(dn.supplier_id) ?? 0) + Math.abs(dn.total_paise),
    );
  }
  const originalsSorted = [...originals].sort((a, b) =>
    a.bill_date < b.bill_date ? -1 : a.bill_date > b.bill_date ? 1 : 0,
  );

  const perPurchase: PurchaseOutstanding[] = [];
  for (const p of originalsSorted) {
    const attached = debitsByOriginalId.get(p.id) ?? [];
    // Legacy pool: consume oldest bill first, only for suppliers that have
    // unattached legacy debit notes.
    const pool = legacyPoolBySupplier.get(p.supplier_id) ?? 0;
    const attachedReduction = attached.reduce(
      (acc, dn) => acc + Math.abs(dn.total_paise),
      0,
    );
    const grossBeforeLegacy = p.total_paise - p.paid_paise - attachedReduction;
    const applyLegacy = Math.min(Math.max(grossBeforeLegacy, 0), pool);
    if (applyLegacy > 0) {
      legacyPoolBySupplier.set(p.supplier_id, pool - applyLegacy);
    }
    const virtualLegacyDn: Purchase[] =
      applyLegacy > 0
        ? [{ ...p, total_paise: -applyLegacy, id: `${p.id}-DN-legacy` }]
        : [];
    const row = computePurchaseRow(
      p,
      [...attached, ...virtualLegacyDn],
      asOfYmd,
    );
    perPurchase.push(row);
  }

  // Any leftover legacy debit-note credit that couldn't be applied to a bill
  // becomes a supplier advance (money the supplier owes back to us).
  const leftoverAdvanceBySupplier = new Map<string, number>();
  for (const [supplierId, remaining] of legacyPoolBySupplier.entries()) {
    if (remaining > 0) leftoverAdvanceBySupplier.set(supplierId, remaining);
  }
  // Similarly, if an attached debit note exceeds its original's remaining
  // balance, computePurchaseRow already caps outstanding at 0 and folds the
  // excess into advance_paise on that row (see grossOutstanding < 0 branch).

  const bucket = new Map<string, SupplierPayable>();
  const grand: SupplierPayable = {
    supplier_id: '',
    bill_count: 0,
    total_billed_paise: 0,
    total_paid_paise: 0,
    total_debit_note_paise: 0,
    opening_balance_paise: 0,
    outstanding_paise: 0,
    advance_paise: 0,
    overdue_count: 0,
    aging: emptyAging(),
  };

  function ensureSupplier(supplierId: string): SupplierPayable {
    let sup = bucket.get(supplierId);
    if (!sup) {
      sup = {
        supplier_id: supplierId,
        bill_count: 0,
        total_billed_paise: 0,
        total_paid_paise: 0,
        total_debit_note_paise: 0,
        opening_balance_paise: 0,
        outstanding_paise: 0,
        advance_paise: 0,
        overdue_count: 0,
        aging: emptyAging(),
      };
      bucket.set(supplierId, sup);
    }
    return sup;
  }

  for (const row of perPurchase) {
    const sup = ensureSupplier(row.supplier_id);
    sup.total_billed_paise += row.grand_total_paise;
    sup.total_paid_paise += row.paid_paise;
    sup.total_debit_note_paise += row.debit_note_paise;
    grand.total_billed_paise += row.grand_total_paise;
    grand.total_paid_paise += row.paid_paise;
    grand.total_debit_note_paise += row.debit_note_paise;

    if (row.outstanding_paise > 0) {
      sup.bill_count += 1;
      sup.outstanding_paise += row.outstanding_paise;
      grand.outstanding_paise += row.outstanding_paise;
      if (row.overdue) {
        sup.overdue_count += 1;
        grand.overdue_count += 1;
      }
      bucketize(row.outstanding_paise, row.days_overdue, sup.aging);
      bucketize(row.outstanding_paise, row.days_overdue, grand.aging);
    }
  }

  for (const [supplierId, adv] of leftoverAdvanceBySupplier.entries()) {
    const sup = ensureSupplier(supplierId);
    sup.advance_paise += adv;
    grand.advance_paise += adv;
  }

  // Supplier advances: money paid but not yet consumed by a bill = asset owed
  // back to us. Adds to `advance_paise` (which for suppliers already carries
  // debit-note leftovers, semantically "credit balance held by supplier").
  for (const adv of advances) {
    if (adv.party_type !== 'supplier') continue;
    if (adv.remaining_paise <= 0) continue;
    const sup = ensureSupplier(adv.party_id);
    sup.advance_paise += adv.remaining_paise;
    grand.advance_paise += adv.remaining_paise;
  }

  // Fold in opening balances. Positive opening = we owed supplier on go-live,
  // treated as outstanding bucketed as "current". Negative opening = supplier
  // held credit for us; lives in advance_paise.
  for (const s of suppliers) {
    const opening = s.opening_balance_paise;
    if (opening === 0) continue;
    const sup = ensureSupplier(s.id);
    sup.opening_balance_paise += opening;
    grand.opening_balance_paise += opening;
    if (opening > 0) {
      sup.outstanding_paise += opening;
      grand.outstanding_paise += opening;
      bucketize(opening, 0, sup.aging);
      bucketize(opening, 0, grand.aging);
    } else {
      sup.advance_paise += -opening;
      grand.advance_paise += -opening;
    }
  }

  const perSupplier = [...bucket.values()].sort(
    (a, b) => b.outstanding_paise - a.outstanding_paise,
  );
  return { perPurchase, perSupplier, totals: grand };
}
